mapper.select:
SELECT r.order_no, s.name AS spot_name, r.slot_date, r.slot_start, r.slot_end, r.quantity, r.total_amount, r.status, r.create_time FROM reserve r JOIN spot s ON s.id = r.spot_id WHERE r.user_id = #{userId}
AND r.status = #{status}
ORDER BY r.create_time DESC, r.id DESC

SELECT id, order_no, slot_id, quantity
FROM reserve
WHERE status = 0
  AND create_time < #{deadline}
LIMIT #{limit}
